58	const ESFERA_STYLES: Record<string, { color: string; bg: string }> = {
59	    FEDERAL: { color: '#3b82f6', bg: 'rgba(59,130,246,0.07)' },
60	    ESTADUAL: { color: '#22d3ee', bg: 'rgba(34,211,238,0.07)' },
61	    MUNICIPAL: { color: '#a78bfa', bg: 'rgba(167,139,250,0.07)' },
