64	function fmtMoic(v: number | undefined) {
65	    if (v === undefined || v === null) return '—';
66	    return `${Number(v).toFixed(2)}x`;
67	}
68	
69	function formatRevisadoEm(value?: string | null): string {
70	    if (!value) return '';
71	    try {
72	        return `${dateFormater(value)} às ${formatToZonedTime(value)}`;
73	    } catch {
74	        return '';
75	    }
76	}
77	
78	function parseMoneyValue(value?: string | number | null) {
79	    if (value === null || value === undefined || value === '') return 0;
80	    if (typeof value === 'number') return Number.isFinite(value) ? value : 0;
81	    const normalized = value
82	        .replace(/R\$\s*/g, '')
83	        .replace(/\.(?=\d{3}(\D|$))/g, '')
84	        .replace(',', '.');
85	    const parsed = Number(normalized);
86	    return Number.isFinite(parsed) ? parsed : 0;
87	}
