121	                        danger
122	                            ? 'border-red-200 bg-red-50/80 text-red-400 hover:border-red-300 hover:text-red-500 dark:border-red-900/30 dark:bg-red-500/6 dark:text-red-400/60 dark:hover:text-red-400'
123	                            : 'border-stroke bg-[#f5f7fa] text-[#536471] hover:border-[#96FF00]/30 hover:text-[#4d8f00] dark:border-[#1a2228] dark:bg-[#0c1117] dark:text-[#3d4850] dark:hover:border-[#96FF00]/20 dark:hover:text-[#96FF00]/60',
124	                    )}
125	                >
126	                    <Icon className="h-3.5 w-3.5 sm:h-3 sm:w-3" aria-hidden />
127	                </button>
