170	function RevisadoBadge({
171	    revisado,
172	    revisadoPor,
173	    revisadoEm,
174	    readOnly,
175	    onToggle,
176	}: RevisadoBadgeProps) {
177	    const wrapperClass = cn(
178	        'inline-flex items-center gap-1.5 rounded-full border px-2 py-[3px] text-[10px] shadow-sm backdrop-blur-sm transition-all duration-200',
179	        revisado
180	            ? 'border-emerald-500/25 bg-linear-to-r from-emerald-500/10 to-emerald-500/3 text-emerald-700 dark:border-emerald-400/20 dark:from-emerald-400/12 dark:to-emerald-400/3 dark:text-emerald-300'
181	            : 'border-red-500/25 bg-red-500/6 text-red-600 dark:border-red-400/20 dark:bg-red-400/8 dark:text-red-400',
182	    );
183	
184	    const interactiveClass = revisado
185	        ? 'hover:border-emerald-500/45 hover:shadow-md hover:shadow-emerald-500/10 active:scale-[0.97] dark:hover:border-emerald-400/40'
186	        : 'hover:border-red-500/45 hover:shadow-md hover:shadow-red-500/10 active:scale-[0.97] dark:hover:border-red-400/40';
187	
188	    const content = (
189	        <>
190	            <span
191	                className={cn(
192	                    'flex h-4 w-4 shrink-0 items-center justify-center rounded-full',
193	                    revisado
194	                        ? 'bg-emerald-500/15 text-emerald-600 dark:bg-emerald-400/15 dark:text-emerald-400'
195	                        : 'bg-red-500/15 text-red-500 dark:bg-red-400/15 dark:text-red-400',
196	                )}
197	            >
198	                {revisado ? (
199	                    <CheckCircle2 className="h-3 w-3" strokeWidth={2.5} />
200	                ) : (
201	                    <XCircle className="h-3 w-3" strokeWidth={2.5} />
202	                )}
203	            </span>
204	            {revisado && revisadoPor ? (
205	                <>
206	                    <Avatar className="h-4 w-4 shrink-0 ring-2 ring-white dark:ring-[#0a0e11]">
207	                        <AvatarImage
208	                            src={revisadoPor.profile_picture ?? undefined}
209	                            alt={revisadoPor.full_name || revisadoPor.username || ''}
210	                        />
211	                        <AvatarFallback className="bg-emerald-600 text-[6px] font-bold text-white">
212	                            {getInitials(revisadoPor.full_name || revisadoPor.username || '')}
213	                        </AvatarFallback>
214	                    </Avatar>
215	                    <span className="max-w-[84px] truncate font-semibold">
216	                        {revisadoPor.full_name || revisadoPor.username}
217	                    </span>
218	                    {revisadoEm && (
219	                        <span className="font-normal tabular-nums opacity-60">
220	                            · {formatRevisadoEm(revisadoEm)}
221	                        </span>
222	                    )}
223	                </>
224	            ) : (
225	                <span className="font-semibold">{revisado ? 'Revisado' : 'Não revisado'}</span>
226	            )}
227	        </>
228	    );
229	
230	    return (
231	        <Tooltip>
232	            <TooltipTrigger asChild>
233	                {readOnly ? (
234	                    <span className={wrapperClass}>{content}</span>
235	                ) : (
236	                    <button
237	                        type="button"
238	                        onClick={onToggle}
239	                        className={cn(wrapperClass, interactiveClass)}
240	                    >
241	                        {content}
242	                    </button>
243	                )}
244	            </TooltipTrigger>
245	            <TooltipContent>
246	                <p className="text-xs">
247	                    {readOnly
248	                        ? `Ativo ${revisado ? 'revisado' : 'não revisado'}`
249	                        : revisado
250	                            ? 'Clique para marcar como não revisado'
251	                            : 'Clique para marcar como revisado'}
252	                </p>
253	            </TooltipContent>
254	        </Tooltip>
255	    );
256	}
