258	export function IndividualCardDetail({
259	    investment,
260	    onEditItem,
261	    externalScenario,
262	    onArchivedClick,
263	    onNewItem,
264	    onExportClick,
265	    onImportHistoryClick,
266	    onCreateCessionarioClick,
267	    onListCessionariosClick,
268	}: IndividualCardDetailProps) {
269	    const scenarioFromAPI = mapScenarioFromAPI(investment.selected_scenario);
270	    const [selectedScenario, setSelectedScenario] = useState<ScenarioKey>(
271	        scenarioFromAPI || 'base',
272	    );
273	    const [isProjectionOpen, setIsProjectionOpen] = useState(false);
274	    const [isDocsOpen, setIsDocsOpen] = useState(false);
275	    const archiveTriggerRef = useRef<HTMLButtonElement>(null);
276	
277	    const userRole = useUserInfoStore((store) => store.data.role);
278	    const currentUserProfile = useUserInfoStore((store) => store.data);
279	    const isInvestidor = (ROLES.INVESTIDOR as readonly string[]).includes(userRole);
280	    const isMaster = userRole === 'MASTER';
281	    const isFromDasi = getTenantFromUrl() === Tenants.DASI;
282	    const isMobile = useIsMobile();
283	
284	    const { mutate: updateScenario, isPending: isUpdatingScenario } = useUpdateSelectedScenario(
285	        investment.id,
286	    );
287	    const { mutate: toggleCessao, isPending: isTogglingCessao } = useUpdateCessaoRegistrada(
288	        investment.id,
289	    );
290	    const { mutate: toggleRevisado } = useUpdateRevisado(investment.id, currentUserProfile);
291	    const { data: detailData } = useQuery(getPostPurchaseByIdQuery(investment.id));
292	
293	    useEffect(() => {
294	        const mapped = mapScenarioFromAPI(investment.selected_scenario);
295	        if (mapped && mapped !== selectedScenario) {
296	            setSelectedScenario(mapped);
297	        }
298	    }, [investment.selected_scenario, selectedScenario]);
299	
300	    useEffect(() => {
301	        if (externalScenario && externalScenario !== selectedScenario) {
302	            setSelectedScenario(externalScenario);
303	            updateScenario(externalScenario as ScenarioType);
304	        }
305	        // eslint-disable-next-line react-hooks/exhaustive-deps
306	    }, [externalScenario]);
307	
308	    const scenario = investment.profitability_scenarios?.[selectedScenario];
309	
310	    // `valor_investido` é Decimal (string) no JSON; o manual continua number.
311	    const valorInvestido =
312	        investment.valor_investido_manual ??
313	        parseNullableDecimal(investment.valor_investido) ??
314	        0;
315	    const valorLiquidoAtual = parseMoneyValue(
316	        detailData?.valor_liquido_disponivel ?? investment.valor_liquido_disponivel,
317	    );
318	    const valorProjetado = parseNullableDecimal(scenario?.valor_projetado) ?? 0;
319	    const ganho = valorProjetado - valorInvestido;
320	
321	    const rawPrincipal =
322	        detailData?.valor_principal_requisicao ?? investment.valor_principal_requisicao;
323	    const rawJuros =
324	        detailData?.juros_atualizado_requisicao ?? investment.juros_atualizado_requisicao;
325	    const rawJurosSelic =
326	        detailData?.juros_selic_atualizado_requisicao ??
327	        investment.juros_selic_atualizado_requisicao;
328	    const rawDeducoes = detailData?.soma_deducoes ?? investment.soma_deducoes;
329	
330	    const valorPrincipal = rawPrincipal != null ? parseMoneyValue(rawPrincipal) : null;
331	    const jurosAtualizado = rawJuros != null ? parseMoneyValue(rawJuros) : null;
332	    const jurosSelicAtualizado = rawJurosSelic != null ? parseMoneyValue(rawJurosSelic) : null;
333	    const somaDeducoes = rawDeducoes != null ? parseMoneyValue(rawDeducoes) : null;
334	
335	    const valorAtualBreakdown = [
336	        { label: 'Principal', value: valorPrincipal, accent: 'text-gray-100' },
337	        { label: 'Juros', value: jurosAtualizado, accent: 'text-gray-100' },
338	        { label: 'Selic', value: jurosSelicAtualizado, accent: 'text-gray-100' },
339	        { label: 'Deduções', value: somaDeducoes, accent: 'text-red-300', negative: true },
340	    ];
341	
342	    const richDetail = (detailData ?? investment) as typeof investment & {
343	        valor_cedente?: string | number | null;
344	        comissao_broker_investidor?: string | number | null;
345	        comissao_broker_ativos?: string | number | null;
346	        comissao_ativos?: string | number | null;
347	    };
348	
349	    const rawValorCedente = richDetail?.valor_cedente;
350	    const rawComissaoAtivos = richDetail?.comissao_ativos;
351	    const rawComissaoBrokerInvestido = richDetail?.comissao_broker_investidor;
352	    const rawComissaoBrokerAtivos = richDetail?.comissao_broker_ativos;
353	
354	    const valorCedente = rawValorCedente != null ? parseMoneyValue(rawValorCedente) : null;
355	    const comissaoAtivos = rawComissaoAtivos != null ? parseMoneyValue(rawComissaoAtivos) : null;
356	    const comissaoBrokerInvestido =
357	        rawComissaoBrokerInvestido != null ? parseMoneyValue(rawComissaoBrokerInvestido) : null;
358	    const comissaoBrokerAtivos =
359	        rawComissaoBrokerAtivos != null ? parseMoneyValue(rawComissaoBrokerAtivos) : null;
360	
361	    const valorInvestidoBreakdown = [
362	        { label: 'Valor ao Cedente', value: valorCedente, accent: 'text-gray-100' },
363	        { label: 'Comissão Ativos', value: comissaoAtivos, accent: 'text-gray-100' },
364	        {
365	            label: 'Comissão Broker Investido',
366	            value: comissaoBrokerInvestido,
367	            accent: 'text-gray-100',
368	        },
369	        {
370	            label: 'Comissão Broker Ativos',
371	            value: comissaoBrokerAtivos,
372	            accent: 'text-gray-100',
373	        },
374	    ];
375	
376	    const dataAquisicao = investment.data_de_aquisicao_manual || investment.data_de_aquisicao;
377	    const dataProjecao = scenario?.data_previsao_pagamento;
378	
379	    const totalRange = valorProjetado - valorInvestido;
380	    const progressPct =
381	        totalRange > 0
382	            ? Math.min(100, Math.max(0, ((valorLiquidoAtual - valorInvestido) / totalRange) * 100))
383	            : 0;
384	
385	    const tir = parseNullableDecimal(scenario?.tir) ?? undefined;
386	    const moic = parseNullableDecimal(scenario?.moic) ?? undefined;
387	
388	    const cessionarios = investment.cessionarios ?? [];
389	    const firstCessionarioName = cessionarios[0]?.nome ?? '-';
390	    const otherCessionariosCount = Math.max(0, cessionarios.length - 1);
391	    const cessionarioLabel =
392	        cessionarios.length > 1
393	            ? `${firstCessionarioName} +${otherCessionariosCount}`
394	            : firstCessionarioName;
395	
396	    const durationLabel = formatDuration(dataAquisicao, dataProjecao || '');
397	    const today = startOfDay(new Date());
398	    const projectionDate = dataProjecao ? startOfDay(new Date(dataProjecao)) : null;
399	    const remainingMonths =
400	        projectionDate && isAfter(projectionDate, today)
401	            ? differenceInCalendarMonths(projectionDate, today)
402	            : 0;
403	    const remainingMonthsLabel =
404	        remainingMonths === 1 ? '1 mês restante' : `${remainingMonths} meses restantes`;
405	
406	    const esferaKey = investment.esfera?.toUpperCase() ?? 'FEDERAL';
407	    const esferaStyle = ESFERA_STYLES[esferaKey] ?? ESFERA_STYLES.FEDERAL;
408	    const esferaLabel = investment.esfera
409	        ? investment.esfera.charAt(0) + investment.esfera.slice(1).toLowerCase()
410	        : '—';
411	
412	    const hasActions =
413	        onArchivedClick ||
414	        onCreateCessionarioClick ||
415	        onListCessionariosClick ||
416	        (isMaster && !isFromDasi);
417	
418	    return (
419	        <>
420	            <div className="relative h-full min-w-0">
421	                {/* Clip-path SVG def — apenas no desktop */}
422	                {!isMobile && (
423	                    <svg className="absolute left-[-999px] top-[-999px] h-0 w-0">
424	                        <defs>
425	                            <clipPath id="ind-detail-clip" clipPathUnits="objectBoundingBox">
426	                                <path
427	                                    transform="scale(0.0010017694 0.002)"
428	                                    d="M0 17.5676C0 7.8653 8.73045 0 19.5 0H1267.65C1271.58 0 1282.56 2.47736 1289.54 8L1486.54 164C1492.54 168.95 1492.54 175.333 1492.54 182V482.433C1492.54 492.135 1483.81 500 1473.04 500H19.5C8.73045 500 0 492.135 0 482.433V17.5676Z"
429	                                />
430	                            </clipPath>
431	                        </defs>
432	                    </svg>
433	                )}
434	
435	                <div
436	                    className={cn(
437	                        'group relative flex h-full min-w-0 flex-col gap-3 overflow-hidden bg-white px-5 py-4 text-[#0b1014] dark:bg-[#0a0e11] dark:text-[#e7ecef]',
438	                        isMobile &&
439	                        'gap-2.5 rounded-2xl border border-[#dce3ea] px-3.5 py-3 dark:border-[#2a3540]',
440	                    )}
441	                    style={{ clipPath: isMobile ? undefined : 'url(#ind-detail-clip)' }}
442	                >
443	                    {/* SVG border overlay — apenas desktop */}
444	                    {!isMobile && (
445	                        <svg
446	                            className="pointer-events-none absolute inset-0 h-full w-full"
447	                            viewBox="0 0 100 100"
448	                            preserveAspectRatio="none"
449	                        >
450	                            <path
451	                                transform="scale(0.0010017694 0.002)"
452	                                d="M0 17.5676C0 7.8653 8.73045 0 19.5 0H1267.65C1271.58 0 1282.56 2.47736 1289.54 8L1486.54 164C1492.54 168.95 1492.54 175.333 1492.54 182V482.433C1492.54 492.135 1483.81 500 1473.04 500H19.5C8.73045 500 0 492.135 0 482.433V17.5676Z"
453	                                fill="none"
454	                                strokeWidth="1.5"
455	                                vectorEffect="non-scaling-stroke"
456	                                className="stroke-[#dce3ea] transition-colors duration-300 group-hover:stroke-[rgba(150,255,0,0.30)] dark:stroke-[#2a3540] dark:group-hover:stroke-[rgba(150,255,0,0.25)]"
457	                            />
458	                        </svg>
459	                    )}
460	
461	                    <div className="pointer-events-none absolute -right-8 -top-8 h-40 w-40 rounded-full bg-[#96FF00]/5 blur-3xl transition-all duration-700 group-hover:h-52 group-hover:w-52 group-hover:bg-[#96FF00]/10 dark:bg-[#96FF00]/[0.07] dark:group-hover:bg-[#96FF00]/16" />
462	
463	                    {/* ── Header: cessão + tags + ações mobile (estrutura original) ── */}
464	                    <div className="relative flex min-w-0 items-start justify-between gap-2">
465	                        <div className="flex min-w-0 flex-1 flex-wrap items-center gap-1.5">
466	                            {/* Indicador / switch de cessão */}
467	                            <Tooltip>
468	                                <TooltipTrigger asChild>
469	                                    <div className="flex items-center">
470	                                        {isInvestidor ? (
471	                                            <span
472	                                                className={cn(
473	                                                    'h-2 w-2 rounded-full',
474	                                                    investment.cessao_registrada
475	                                                        ? 'bg-[#96FF00]'
476	                                                        : 'bg-red-500',
477	                                                )}
478	                                            />
479	                                        ) : (
480	                                            <div className="flex items-center gap-1.5">
481	                                                <Switch
482	                                                    variant="animated"
483	                                                    checked={!!investment.cessao_registrada}
484	                                                    onCheckedChange={(v) => toggleCessao(v)}
485	                                                    disabled={isTogglingCessao}
486	                                                    className="data-[state=unchecked]:bg-red-400"
487	                                                />
488	                                                {isTogglingCessao && (
489	                                                    <Loader2
490	                                                        size={10}
491	                                                        className="animate-spin text-[#8a9097]"
492	                                                    />
493	                                                )}
494	                                            </div>
495	                                        )}
496	                                    </div>
497	                                </TooltipTrigger>
498	                                <TooltipContent>
499	                                    <p className="text-xs">
500	                                        Cessão{' '}
