'use client';

import { Component as CircularCommandMenu } from '@/components/circular-command-menu';
import { ArchivePostPurchaseModal } from '@/components/Modals/PostPurchase/ArchivePostPurchaseModal';
import { PostPurchaseDocumentsModal } from '@/components/Modals/PostPurchaseDocumentsModal';
import { ImportadoBadge } from '@/components/PostAquisition/shared/ImportadoBadge';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Switch } from '@/components/ui/switch';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { ROLES } from '@/constants/roles';
import { ScenarioType } from '@/enums/scenario.enum';
import { Tenants } from '@/enums/tenants.enum';
import dateFormater from '@/functions/formaters/dateFormater';
import { formatCurrency } from '@/functions/formaters/formatCurrency';
import { formatToZonedTime } from '@/functions/formaters/formatToZonedTime';
import { getInitials } from '@/functions/formaters/getInitials';
import { parseNullableDecimal } from '@/functions/finance/comissao-ativos';
import { AvisoCenarioCalcBanner } from '@/components/PostAquisition/shared/AvisoCenarioCalc';
import { mapScenarioFromAPI } from '@/functions/post-purchase/scenario';
import {
    useUpdateCessaoRegistrada,
    useUpdateRevisado,
    useUpdateSelectedScenario,
} from '@/hooks/mutations/post-aquisition';
import { getPostPurchaseByIdQuery } from '@/hooks/queries/post-purchase';
import { useIsMobile } from '@/hooks/use-mobile';
import { cn } from '@/lib/utils';
import { useUserInfoStore } from '@/store/userInfo';
import { RevisadoPor } from '@/types/posAquisicao';
import { getTenantFromUrl } from '@/utils/getHostFromUrl';
import { useQuery } from '@tanstack/react-query';
import { differenceInCalendarMonths, isAfter, startOfDay } from 'date-fns';
import {
    Archive,
    CheckCircle2,
    FileClock,
    FileSpreadsheet,
    FolderOpen,
    Loader2,
    LucideIcon,
    Pencil,
    Plus,
    UserPlus,
    Users,
    XCircle,
} from 'lucide-react';
import { useEffect, useRef, useState } from 'react';
import { PosAquisicaoWithCedentes, ScenarioKey } from '../../types';
import { formatDate, formatDuration } from '../../utils';
import { ProjectionEvolutionModal } from '../Modals/ProjectionEvolutionModal';

const SCENARIO_LABELS: Record<ScenarioKey, string> = {
    base: 'Base',
    optimistic: 'Otimista',
    conservative: 'Conservador',
};

const ESFERA_STYLES: Record<string, { color: string; bg: string }> = {
    FEDERAL: { color: '#3b82f6', bg: 'rgba(59,130,246,0.07)' },
    ESTADUAL: { color: '#22d3ee', bg: 'rgba(34,211,238,0.07)' },
    MUNICIPAL: { color: '#a78bfa', bg: 'rgba(167,139,250,0.07)' },
};

function fmtMoic(v: number | undefined) {
    if (v === undefined || v === null) return '—';
    return `${Number(v).toFixed(2)}x`;
}

function formatRevisadoEm(value?: string | null): string {
    if (!value) return '';
    try {
        return `${dateFormater(value)} às ${formatToZonedTime(value)}`;
    } catch {
        return '';
    }
}

function parseMoneyValue(value?: string | number | null) {
    if (value === null || value === undefined || value === '') return 0;
    if (typeof value === 'number') return Number.isFinite(value) ? value : 0;
    const normalized = value
        .replace(/R\$\s*/g, '')
        .replace(/\.(?=\d{3}(\D|$))/g, '')
        .replace(',', '.');
    const parsed = Number(normalized);
    return Number.isFinite(parsed) ? parsed : 0;
}

interface IndividualCardDetailProps {
    investment: PosAquisicaoWithCedentes;
    onEditItem?: (investmentId: string) => void;
    externalScenario?: ScenarioKey;
    onArchivedClick?: () => void;
    onNewItem?: () => void;
    onExportClick?: () => void;
    onImportHistoryClick?: () => void;
    onCreateCessionarioClick?: () => void;
    onListCessionariosClick?: () => void;
}

function ActionBtn({
    icon: Icon,
    label,
    onClick,
    danger,
}: {
    icon: LucideIcon;
    label: string;
    onClick?: () => void;
    danger?: boolean;
}) {
    return (
        <Tooltip>
            <TooltipTrigger asChild>
                <button
                    type="button"
                    onClick={onClick}
                    aria-label={label}
                    className={cn(
                        'flex h-9 w-9 shrink-0 cursor-pointer items-center justify-center rounded-lg border transition-colors duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#96FF00]/45 sm:h-[26px] sm:w-[26px]',
                        danger
                            ? 'border-red-200 bg-red-50/80 text-red-400 hover:border-red-300 hover:text-red-500 dark:border-red-900/30 dark:bg-red-500/6 dark:text-red-400/60 dark:hover:text-red-400'
                            : 'border-stroke bg-[#f5f7fa] text-[#536471] hover:border-[#96FF00]/30 hover:text-[#4d8f00] dark:border-[#1a2228] dark:bg-[#0c1117] dark:text-[#3d4850] dark:hover:border-[#96FF00]/20 dark:hover:text-[#96FF00]/60',
                    )}
                >
                    <Icon className="h-3.5 w-3.5 sm:h-3 sm:w-3" aria-hidden />
                </button>
            </TooltipTrigger>
            <TooltipContent side="bottom">
                <p className="text-xs">{label}</p>
            </TooltipContent>
        </Tooltip>
    );
}

function DesktopActionOrb({
    icon: Icon,
    label,
    onClick,
}: {
    icon: LucideIcon;
    label: string;
    onClick?: () => void;
}) {
    return (
        <div className="group relative shrink-0">
            <button
                type="button"
                onClick={onClick}
                aria-label={label}
                className="flex h-9 w-9 cursor-pointer items-center justify-center rounded-full border-2 border-[#96FF00] bg-primary text-primary-foreground shadow-lg transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#96FF00]/45 xl:h-10 xl:w-10"
            >
                <Icon className="h-3.5 w-3.5 xl:h-4 xl:w-4" aria-hidden />
            </button>
            <div className="pointer-events-none absolute left-1/2 top-full z-30 mt-2 -translate-x-1/2 whitespace-nowrap rounded-md border border-border bg-popover px-2 py-1 text-xs text-popover-foreground opacity-0 shadow-md transition-opacity group-hover:opacity-100">
                {label}
            </div>
        </div>
    );
}

interface RevisadoBadgeProps {
    revisado: boolean;
    revisadoPor?: RevisadoPor | null;
    revisadoEm?: string | null;
    readOnly: boolean;
    onToggle: () => void;
}

function RevisadoBadge({
    revisado,
    revisadoPor,
    revisadoEm,
    readOnly,
    onToggle,
}: RevisadoBadgeProps) {
    const wrapperClass = cn(
        'inline-flex items-center gap-1.5 rounded-full border px-2 py-[3px] text-[10px] shadow-sm backdrop-blur-sm transition-all duration-200',
        revisado
            ? 'border-emerald-500/25 bg-linear-to-r from-emerald-500/10 to-emerald-500/3 text-emerald-700 dark:border-emerald-400/20 dark:from-emerald-400/12 dark:to-emerald-400/3 dark:text-emerald-300'
            : 'border-red-500/25 bg-red-500/6 text-red-600 dark:border-red-400/20 dark:bg-red-400/8 dark:text-red-400',
    );

    const interactiveClass = revisado
        ? 'hover:border-emerald-500/45 hover:shadow-md hover:shadow-emerald-500/10 active:scale-[0.97] dark:hover:border-emerald-400/40'
        : 'hover:border-red-500/45 hover:shadow-md hover:shadow-red-500/10 active:scale-[0.97] dark:hover:border-red-400/40';

    const content = (
        <>
            <span
                className={cn(
                    'flex h-4 w-4 shrink-0 items-center justify-center rounded-full',
                    revisado
                        ? 'bg-emerald-500/15 text-emerald-600 dark:bg-emerald-400/15 dark:text-emerald-400'
                        : 'bg-red-500/15 text-red-500 dark:bg-red-400/15 dark:text-red-400',
                )}
            >
                {revisado ? (
                    <CheckCircle2 className="h-3 w-3" strokeWidth={2.5} />
                ) : (
                    <XCircle className="h-3 w-3" strokeWidth={2.5} />
                )}
            </span>
            {revisado && revisadoPor ? (
                <>
                    <Avatar className="h-4 w-4 shrink-0 ring-2 ring-white dark:ring-[#0a0e11]">
                        <AvatarImage
                            src={revisadoPor.profile_picture ?? undefined}
                            alt={revisadoPor.full_name || revisadoPor.username || ''}
                        />
                        <AvatarFallback className="bg-emerald-600 text-[6px] font-bold text-white">
                            {getInitials(revisadoPor.full_name || revisadoPor.username || '')}
                        </AvatarFallback>
                    </Avatar>
                    <span className="max-w-[84px] truncate font-semibold">
                        {revisadoPor.full_name || revisadoPor.username}
                    </span>
                    {revisadoEm && (
                        <span className="font-normal tabular-nums opacity-60">
                            · {formatRevisadoEm(revisadoEm)}
                        </span>
                    )}
                </>
            ) : (
                <span className="font-semibold">{revisado ? 'Revisado' : 'Não revisado'}</span>
            )}
        </>
    );

    return (
        <Tooltip>
            <TooltipTrigger asChild>
                {readOnly ? (
                    <span className={wrapperClass}>{content}</span>
                ) : (
                    <button
                        type="button"
                        onClick={onToggle}
                        className={cn(wrapperClass, interactiveClass)}
                    >
                        {content}
                    </button>
                )}
            </TooltipTrigger>
            <TooltipContent>
                <p className="text-xs">
                    {readOnly
                        ? `Ativo ${revisado ? 'revisado' : 'não revisado'}`
                        : revisado
                            ? 'Clique para marcar como não revisado'
                            : 'Clique para marcar como revisado'}
                </p>
            </TooltipContent>
        </Tooltip>
    );
}

export function IndividualCardDetail({
    investment,
    onEditItem,
    externalScenario,
    onArchivedClick,
    onNewItem,
    onExportClick,
    onImportHistoryClick,
    onCreateCessionarioClick,
    onListCessionariosClick,
}: IndividualCardDetailProps) {
    const scenarioFromAPI = mapScenarioFromAPI(investment.selected_scenario);
    const [selectedScenario, setSelectedScenario] = useState<ScenarioKey>(
        scenarioFromAPI || 'base',
    );
    const [isProjectionOpen, setIsProjectionOpen] = useState(false);
    const [isDocsOpen, setIsDocsOpen] = useState(false);
    const archiveTriggerRef = useRef<HTMLButtonElement>(null);

    const userRole = useUserInfoStore((store) => store.data.role);
    const currentUserProfile = useUserInfoStore((store) => store.data);
    const isInvestidor = (ROLES.INVESTIDOR as readonly string[]).includes(userRole);
    const isMaster = userRole === 'MASTER';
    const isFromDasi = getTenantFromUrl() === Tenants.DASI;
    const isMobile = useIsMobile();

    const { mutate: updateScenario, isPending: isUpdatingScenario } = useUpdateSelectedScenario(
        investment.id,
    );
    const { mutate: toggleCessao, isPending: isTogglingCessao } = useUpdateCessaoRegistrada(
        investment.id,
    );
    const { mutate: toggleRevisado } = useUpdateRevisado(investment.id, currentUserProfile);
    const { data: detailData } = useQuery(getPostPurchaseByIdQuery(investment.id));

    useEffect(() => {
        const mapped = mapScenarioFromAPI(investment.selected_scenario);
        if (mapped && mapped !== selectedScenario) {
            setSelectedScenario(mapped);
        }
    }, [investment.selected_scenario, selectedScenario]);

    useEffect(() => {
        if (externalScenario && externalScenario !== selectedScenario) {
            setSelectedScenario(externalScenario);
            updateScenario(externalScenario as ScenarioType);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [externalScenario]);

    const scenario = investment.profitability_scenarios?.[selectedScenario];

    // `valor_investido` é Decimal (string) no JSON; o manual continua number.
    const valorInvestido =
        investment.valor_investido_manual ??
        parseNullableDecimal(investment.valor_investido) ??
        0;
    const valorLiquidoAtual = parseMoneyValue(
        detailData?.valor_liquido_disponivel ?? investment.valor_liquido_disponivel,
    );
    const valorProjetado = parseNullableDecimal(scenario?.valor_projetado) ?? 0;
    const ganho = valorProjetado - valorInvestido;

    const rawPrincipal =
        detailData?.valor_principal_requisicao ?? investment.valor_principal_requisicao;
    const rawJuros =
        detailData?.juros_atualizado_requisicao ?? investment.juros_atualizado_requisicao;
    const rawJurosSelic =
        detailData?.juros_selic_atualizado_requisicao ??
        investment.juros_selic_atualizado_requisicao;
    const rawDeducoes = detailData?.soma_deducoes ?? investment.soma_deducoes;

    const valorPrincipal = rawPrincipal != null ? parseMoneyValue(rawPrincipal) : null;
    const jurosAtualizado = rawJuros != null ? parseMoneyValue(rawJuros) : null;
    const jurosSelicAtualizado = rawJurosSelic != null ? parseMoneyValue(rawJurosSelic) : null;
    const somaDeducoes = rawDeducoes != null ? parseMoneyValue(rawDeducoes) : null;

    const valorAtualBreakdown = [
        { label: 'Principal', value: valorPrincipal, accent: 'text-gray-100' },
        { label: 'Juros', value: jurosAtualizado, accent: 'text-gray-100' },
        { label: 'Selic', value: jurosSelicAtualizado, accent: 'text-gray-100' },
        { label: 'Deduções', value: somaDeducoes, accent: 'text-red-300', negative: true },
    ];

    const richDetail = (detailData ?? investment) as typeof investment & {
        valor_cedente?: string | number | null;
        comissao_broker_investidor?: string | number | null;
        comissao_broker_ativos?: string | number | null;
        comissao_ativos?: string | number | null;
    };

    const rawValorCedente = richDetail?.valor_cedente;
    const rawComissaoAtivos = richDetail?.comissao_ativos;
    const rawComissaoBrokerInvestido = richDetail?.comissao_broker_investidor;
    const rawComissaoBrokerAtivos = richDetail?.comissao_broker_ativos;

    const valorCedente = rawValorCedente != null ? parseMoneyValue(rawValorCedente) : null;
    const comissaoAtivos = rawComissaoAtivos != null ? parseMoneyValue(rawComissaoAtivos) : null;
    const comissaoBrokerInvestido =
        rawComissaoBrokerInvestido != null ? parseMoneyValue(rawComissaoBrokerInvestido) : null;
    const comissaoBrokerAtivos =
        rawComissaoBrokerAtivos != null ? parseMoneyValue(rawComissaoBrokerAtivos) : null;

    const valorInvestidoBreakdown = [
        { label: 'Valor ao Cedente', value: valorCedente, accent: 'text-gray-100' },
        { label: 'Comissão Ativos', value: comissaoAtivos, accent: 'text-gray-100' },
        {
            label: 'Comissão Broker Investido',
            value: comissaoBrokerInvestido,
            accent: 'text-gray-100',
        },
        {
            label: 'Comissão Broker Ativos',
            value: comissaoBrokerAtivos,
            accent: 'text-gray-100',
        },
    ];

    const dataAquisicao = investment.data_de_aquisicao_manual || investment.data_de_aquisicao;
    const dataProjecao = scenario?.data_previsao_pagamento;

    const totalRange = valorProjetado - valorInvestido;
    const progressPct =
        totalRange > 0
            ? Math.min(100, Math.max(0, ((valorLiquidoAtual - valorInvestido) / totalRange) * 100))
            : 0;

    const tir = parseNullableDecimal(scenario?.tir) ?? undefined;
    const moic = parseNullableDecimal(scenario?.moic) ?? undefined;

    const cessionarios = investment.cessionarios ?? [];
    const firstCessionarioName = cessionarios[0]?.nome ?? '-';
    const otherCessionariosCount = Math.max(0, cessionarios.length - 1);
    const cessionarioLabel =
        cessionarios.length > 1
            ? `${firstCessionarioName} +${otherCessionariosCount}`
            : firstCessionarioName;

    const durationLabel = formatDuration(dataAquisicao, dataProjecao || '');
    const today = startOfDay(new Date());
    const projectionDate = dataProjecao ? startOfDay(new Date(dataProjecao)) : null;
    const remainingMonths =
        projectionDate && isAfter(projectionDate, today)
            ? differenceInCalendarMonths(projectionDate, today)
            : 0;
    const remainingMonthsLabel =
        remainingMonths === 1 ? '1 mês restante' : `${remainingMonths} meses restantes`;

    const esferaKey = investment.esfera?.toUpperCase() ?? 'FEDERAL';
    const esferaStyle = ESFERA_STYLES[esferaKey] ?? ESFERA_STYLES.FEDERAL;
    const esferaLabel = investment.esfera
        ? investment.esfera.charAt(0) + investment.esfera.slice(1).toLowerCase()
        : '—';

    const hasActions =
        onArchivedClick ||
        onCreateCessionarioClick ||
        onListCessionariosClick ||
        (isMaster && !isFromDasi);

    return (
        <>
            <div className="relative h-full min-w-0">
                {/* Clip-path SVG def — apenas no desktop */}
                {!isMobile && (
                    <svg className="absolute left-[-999px] top-[-999px] h-0 w-0">
                        <defs>
                            <clipPath id="ind-detail-clip" clipPathUnits="objectBoundingBox">
                                <path
                                    transform="scale(0.0010017694 0.002)"
                                    d="M0 17.5676C0 7.8653 8.73045 0 19.5 0H1267.65C1271.58 0 1282.56 2.47736 1289.54 8L1486.54 164C1492.54 168.95 1492.54 175.333 1492.54 182V482.433C1492.54 492.135 1483.81 500 1473.04 500H19.5C8.73045 500 0 492.135 0 482.433V17.5676Z"
                                />
                            </clipPath>
                        </defs>
                    </svg>
                )}

                <div
                    className={cn(
                        'group relative flex h-full min-w-0 flex-col gap-3 overflow-hidden bg-white px-5 py-4 text-[#0b1014] dark:bg-[#0a0e11] dark:text-[#e7ecef]',
                        isMobile &&
                        'gap-2.5 rounded-2xl border border-[#dce3ea] px-3.5 py-3 dark:border-[#2a3540]',
                    )}
                    style={{ clipPath: isMobile ? undefined : 'url(#ind-detail-clip)' }}
                >
                    {/* SVG border overlay — apenas desktop */}
                    {!isMobile && (
                        <svg
                            className="pointer-events-none absolute inset-0 h-full w-full"
                            viewBox="0 0 100 100"
                            preserveAspectRatio="none"
                        >
                            <path
                                transform="scale(0.0010017694 0.002)"
                                d="M0 17.5676C0 7.8653 8.73045 0 19.5 0H1267.65C1271.58 0 1282.56 2.47736 1289.54 8L1486.54 164C1492.54 168.95 1492.54 175.333 1492.54 182V482.433C1492.54 492.135 1483.81 500 1473.04 500H19.5C8.73045 500 0 492.135 0 482.433V17.5676Z"
                                fill="none"
                                strokeWidth="1.5"
                                vectorEffect="non-scaling-stroke"
                                className="stroke-[#dce3ea] transition-colors duration-300 group-hover:stroke-[rgba(150,255,0,0.30)] dark:stroke-[#2a3540] dark:group-hover:stroke-[rgba(150,255,0,0.25)]"
                            />
                        </svg>
                    )}

                    <div className="pointer-events-none absolute -right-8 -top-8 h-40 w-40 rounded-full bg-[#96FF00]/5 blur-3xl transition-all duration-700 group-hover:h-52 group-hover:w-52 group-hover:bg-[#96FF00]/10 dark:bg-[#96FF00]/[0.07] dark:group-hover:bg-[#96FF00]/16" />

                    {/* ── Header: cessão + tags + ações mobile (estrutura original) ── */}
                    <div className="relative flex min-w-0 items-start justify-between gap-2">
                        <div className="flex min-w-0 flex-1 flex-wrap items-center gap-1.5">
                            {/* Indicador / switch de cessão */}
                            <Tooltip>
                                <TooltipTrigger asChild>
                                    <div className="flex items-center">
                                        {isInvestidor ? (
                                            <span
                                                className={cn(
                                                    'h-2 w-2 rounded-full',
                                                    investment.cessao_registrada
                                                        ? 'bg-[#96FF00]'
                                                        : 'bg-red-500',
                                                )}
                                            />
                                        ) : (
                                            <div className="flex items-center gap-1.5">
                                                <Switch
                                                    variant="animated"
                                                    checked={!!investment.cessao_registrada}
                                                    onCheckedChange={(v) => toggleCessao(v)}
                                                    disabled={isTogglingCessao}
                                                    className="data-[state=unchecked]:bg-red-400"
                                                />
                                                {isTogglingCessao && (
                                                    <Loader2
                                                        size={10}
                                                        className="animate-spin text-[#8a9097]"
                                                    />
                                                )}
                                            </div>
                                        )}
                                    </div>
                                </TooltipTrigger>
                                <TooltipContent>
                                    <p className="text-xs">
                                        Cessão{' '}
                                        {investment.cessao_registrada
                                            ? 'Registrada'
                                            : 'Não registrada'}
                                    </p>
                                </TooltipContent>
                            </Tooltip>

                            {/* Esfera */}
                            <span
                                className="rounded-full px-2 py-0.5 text-[10px] font-semibold tracking-wide"
                                style={{ color: esferaStyle.color, background: esferaStyle.bg }}
                            >
                                {esferaLabel}
                            </span>

                            {/* Tribunal */}
                            <span className="rounded-full border border-stroke bg-[#f5f7fa] px-2 py-0.5 text-[10px] font-medium text-[#536471] dark:border-[#1a2228] dark:bg-[#0c1117] dark:text-[#5d6770]">
                                {investment.tribunal}
                            </span>

                            {/* LOA */}
                            <span className="rounded-full border border-stroke bg-[#f5f7fa] px-2 py-0.5 text-[10px] font-medium text-[#536471] dark:border-[#1a2228] dark:bg-[#0c1117] dark:text-[#5d6770]">
                                LOA {investment.loa}
                            </span>

                            {/* Revisado */}
                            <RevisadoBadge
                                revisado={!!investment.revisado}
                                revisadoPor={investment.revisado_por}
                                revisadoEm={investment.revisado_em}
                                readOnly={isInvestidor}
                                onToggle={() => toggleRevisado(!investment.revisado)}
                            />

                            {/* Importado */}
                            <ImportadoBadge
                                importado={!!investment.importado}
                                variant="detail"
                            />
                        </div>

                        {/* Botões de ação — apenas mobile (desktop: recorte) */}
                        {isMobile && hasActions && (
                            <div
                                className="flex max-w-[48%] shrink-0 flex-wrap items-center justify-end gap-1"
                                role="toolbar"
                                aria-label="Ações do ativo"
                            >
                                {onArchivedClick && (
                                    <ActionBtn
                                        icon={FolderOpen}
                                        label="Ativos Arquivados"
                                        onClick={onArchivedClick}
                                    />
                                )}
                                {onCreateCessionarioClick && (
                                    <ActionBtn
                                        icon={UserPlus}
                                        label="Cadastrar cessionário"
                                        onClick={onCreateCessionarioClick}
                                    />
                                )}
                                {onListCessionariosClick && (
                                    <ActionBtn
                                        icon={Users}
                                        label="Cessionários cadastrados"
                                        onClick={onListCessionariosClick}
                                    />
                                )}
                                {isMaster && !isFromDasi && (
                                    <>
                                        <ActionBtn
                                            icon={Archive}
                                            label="Arquivar este ativo"
                                            danger
                                            onClick={() => archiveTriggerRef.current?.click()}
                                        />
                                        <ActionBtn
                                            icon={Pencil}
                                            label="Editar ativo"
                                            onClick={() => onEditItem?.(investment.id)}
                                        />
                                        <ActionBtn
                                            icon={Plus}
                                            label="Novo ativo"
                                            onClick={onNewItem}
                                        />
                                    </>
                                )}
                            </div>
                        )}
                    </div>

                    {/* Lido do item da listagem, que é de onde descem TIR, MOIC,
                        projetado e ganho — um banner cobre os quatro. */}
                    <AvisoCenarioCalcBanner recurso={investment} />

                    {/* ── Credor + cessionário + ente + TIR ── */}
                    <div className="relative">
                        <div className="text-[13px] font-bold uppercase tracking-wide text-[#0b1014] dark:text-[#c8d4dc]">
                            {investment.credor}
                        </div>
                        <Tooltip>
                            <TooltipTrigger asChild>
                                <p className="mt-0.5 w-fit max-w-full cursor-help text-[10px] font-medium text-[#8a9097] underline decoration-dotted underline-offset-4 dark:text-[#3d4850]">
                                    {cessionarioLabel}
                                </p>
                            </TooltipTrigger>
                            <TooltipContent
                                side="top"
                                align="start"
                                className="w-[280px] rounded-xl border border-border bg-white p-0 shadow-xl dark:bg-boxdark-2"
                            >
                                <div className="border-b border-border bg-gray-50/50 px-4 py-3 dark:bg-boxdark">
                                    <p className="text-[11px] font-semibold uppercase tracking-[0.2em] text-gray-500 dark:text-gray-400">
                                        Cessionários
                                    </p>
                                </div>
                                <div className="space-y-3 px-4 py-3">
                                    {cessionarios.length ? (
                                        cessionarios.map((c) => (
                                            <div
                                                key={c.id}
                                                className="flex items-center justify-between gap-4"
                                            >
                                                <span
                                                    className="truncate text-sm font-medium text-gray-900 dark:text-white"
                                                    title={c.nome}
                                                >
                                                    {c.nome}
                                                </span>
                                                <span className="text-gray-600 rounded border px-2 py-0.5 text-xs dark:text-gray-300">
                                                    {c.percentual_cessao ?? '0'}%
                                                </span>
                                            </div>
                                        ))
                                    ) : (
                                        <div className="text-sm text-gray-500">-</div>
                                    )}
                                </div>
                            </TooltipContent>
                        </Tooltip>
                        <div className="mt-0.5 text-[10px] font-medium text-[#8a9097] dark:text-[#3d4850]">
                            {investment.ente_devedor}
                        </div>

                        {/* TIR */}
                        <div className="mt-2.5 flex items-baseline gap-1">
                            <span className="text-[30px] font-light tabular-nums leading-none tracking-tight text-[#0b1014] dark:text-white">
                                {tir !== undefined ? (tir * 100).toFixed(2) : '—'}
                            </span>
                            <span className="text-[15px] font-light text-[#4d8f00] dark:text-[#96FF00]/50">
                                %
                            </span>
                            {isUpdatingScenario && (
                                <Loader2 size={11} className="ml-1 animate-spin text-[#8a9097]" />
                            )}
                        </div>
                        <div className="text-[10px] font-medium text-[#8a9097] dark:text-[#3d4850]">
                            TIR · Cenário {SCENARIO_LABELS[selectedScenario]}
                        </div>
                    </div>

                    {/* ── Três colunas financeiras (estrutura do print) ── */}
                    <div className="grid min-w-0 grid-cols-[minmax(0,1fr)_minmax(0,1.35fr)_minmax(0,1fr)] overflow-hidden rounded-[10px] border border-stroke dark:border-[#1a2228]">
                        {/* Investido */}
                        <div className="flex min-w-0 flex-col justify-center gap-1 border-r border-stroke bg-white px-2.5 py-3 dark:border-[#1a2228] dark:bg-[#0a0e11] sm:gap-1.5 sm:px-4 sm:py-5 xl:px-5">
                            <Tooltip>
                                <TooltipTrigger asChild>
                                    <span className="w-fit cursor-help text-[8px] font-bold uppercase tracking-widest text-[#8a9097] underline decoration-dotted underline-offset-4 dark:text-[#3d4850] sm:text-[9px]">
                                        Investido
                                    </span>
                                </TooltipTrigger>
                                <TooltipContent
                                    side="top"
                                    align="center"
                                    className="w-[280px] rounded-xl border border-emerald-900/30 bg-[#0b1f1a] p-0 text-white shadow-xl"
                                >
                                    <div className="border-b border-white/10 px-4 py-3">
                                        <p className="text-[11px] font-semibold uppercase tracking-[0.35em] text-emerald-300/90">
                                            Memória de cálculo
                                        </p>
                                        <p className="mt-1 text-sm font-medium text-white">
                                            Composição do valor investido
                                        </p>
                                    </div>
                                    <div className="space-y-2 px-4 py-3">
                                        {valorInvestidoBreakdown.map((item) => (
                                            <div
                                                key={item.label}
                                                className="flex items-center justify-between gap-2 text-sm"
                                            >
                                                <span className="text-white/70">{item.label}</span>
                                                <span className={cn('font-medium', item.accent)}>
                                                    {item.value != null
                                                        ? formatCurrency(item.value)
                                                        : '--'}
                                                </span>
                                            </div>
                                        ))}
                                    </div>
                                    <div className="flex items-center justify-between rounded-b-xl bg-white/5 px-4 py-3">
                                        <span className="text-xs font-semibold uppercase tracking-[0.25em] text-white/60">
                                            Total
                                        </span>
                                        <span className="text-base font-semibold text-emerald-300">
                                            {formatCurrency(valorInvestido)}
                                        </span>
                                    </div>
                                </TooltipContent>
                            </Tooltip>
                            <span className="min-w-0 truncate text-[11px] font-semibold tabular-nums leading-tight text-[#0b1014] dark:text-white sm:text-[14px] xl:text-[16px]">
                                <span className="mr-0.5 text-[8px] text-[#4d8f00] dark:text-[#96FF00]/40 sm:text-[10px] xl:text-[11px]">
                                    R$
                                </span>
                                {formatCurrency(valorInvestido).replace(/R\$\s*/g, '')}
                            </span>
                            <span className="text-[9px] text-[#8a9097] dark:text-[#3d4850] sm:text-[11px]">
                                {dataAquisicao ? dateFormater(dataAquisicao) : '—'}
                            </span>
                        </div>

                        {/* Valor Atual — destaque central */}
                        <div className="relative flex min-w-0 flex-col items-center justify-center gap-0.5 bg-white px-1.5 py-3 text-center dark:bg-[#0a0e11] sm:gap-1.5 sm:px-3 sm:py-5 xl:px-4">
                            <div className="pointer-events-none absolute inset-0 border-x border-[#96FF00]/20 bg-[#96FF00]/6 dark:border-[#96FF00]/8 dark:bg-[#96FF00]/4" />
                            <Tooltip>
                                <TooltipTrigger asChild>
                                    <span className="relative z-[1] cursor-help text-[8px] font-bold uppercase tracking-wider text-[#4d8f00] underline decoration-dotted underline-offset-2 dark:text-[#96FF00]/50 sm:text-[10px] sm:underline-offset-4">
                                        <span className="sm:hidden">Valor Atual</span>
                                        <span className="hidden sm:inline">
                                            Valor Atual do Ativo
                                        </span>
                                    </span>
                                </TooltipTrigger>
                                <TooltipContent
                                    side="top"
                                    align="center"
                                    className="w-[280px] rounded-xl border border-emerald-900/30 bg-[#0b1f1a] p-0 text-white shadow-xl"
                                >
                                    <div className="border-b border-white/10 px-4 py-3">
                                        <p className="text-[11px] font-semibold uppercase tracking-[0.35em] text-emerald-300/90">
                                            Memória de cálculo
                                        </p>
                                        <p className="mt-1 text-sm font-medium text-white">
                                            Composição do valor atual
                                        </p>
                                    </div>
                                    <div className="space-y-2 px-4 py-3">
                                        {valorAtualBreakdown.map((item) => (
                                            <div
                                                key={item.label}
                                                className="flex items-center justify-between gap-4 text-sm"
                                            >
                                                <span className="text-white/70">{item.label}</span>
                                                <span className={cn('font-medium', item.accent)}>
                                                    {item.value != null
                                                        ? `${item.negative ? '-' : ''}${formatCurrency(item.value)}`
                                                        : '—'}
                                                </span>
                                            </div>
                                        ))}
                                    </div>
                                    <div className="flex items-center justify-between rounded-b-xl bg-white/5 px-4 py-3">
                                        <span className="text-xs font-semibold uppercase tracking-[0.25em] text-white/60">
                                            Total
                                        </span>
                                        <span className="text-base font-semibold text-emerald-300">
                                            {formatCurrency(valorLiquidoAtual)}
                                        </span>
                                    </div>
                                </TooltipContent>
                            </Tooltip>
                            <span className="relative z-[1] min-w-0 max-w-full truncate text-[15px] font-semibold tabular-nums leading-none tracking-tight text-[#64bb01] dark:text-[#96FF00]/80 sm:text-[24px] xl:text-[34px]">
                                <span className="mr-0.5 text-[9px] font-semibold sm:text-[12px] xl:text-[14px]">
                                    R$
                                </span>
                                {formatCurrency(valorLiquidoAtual).replace(/R\$\s*/g, '')}
                            </span>
                            <span className="relative z-[1] max-w-full truncate text-[9px] leading-tight text-[#536471] dark:text-[#5d6770] sm:text-[12px]">
                                {valorLiquidoAtual - valorInvestido >= 0 ? '+' : ''}
                                {formatCurrency(valorLiquidoAtual - valorInvestido).replace(
                                    /R\$\s*/g,
                                    'R$ ',
                                )}
                                {' · '}
                                <span className="font-semibold text-[#4d8f00] dark:text-[#96FF00]/50">
                                    {valorInvestido > 0
                                        ? (valorLiquidoAtual / valorInvestido).toFixed(2)
                                        : '0.00'}
                                    x
                                </span>
                            </span>
                        </div>

                        {/* Projetado */}
                        <div className="flex min-w-0 flex-col items-end justify-center gap-1 border-l border-stroke bg-white px-2.5 py-3 text-right dark:border-[#1a2228] dark:bg-[#0a0e11] sm:gap-1.5 sm:px-4 sm:py-5 xl:px-5">
                            <span className="text-[8px] font-bold uppercase tracking-widest text-[#8a9097] dark:text-[#3d4850] sm:text-[9px]">
                                Projetado
                            </span>
                            <span className="min-w-0 max-w-full truncate text-[11px] font-semibold tabular-nums leading-tight text-[#0b1014] dark:text-white sm:text-[14px] xl:text-[16px]">
                                <span className="mr-0.5 text-[8px] text-[#4d8f00] dark:text-[#96FF00]/40 sm:text-[10px] xl:text-[11px]">
                                    R$
                                </span>
                                {valorProjetado > 0
                                    ? formatCurrency(valorProjetado).replace(/R\$\s*/g, '')
                                    : '—'}
                            </span>
                            <span className="text-[9px] text-[#8a9097] dark:text-[#3d4850] sm:text-[11px]">
                                {dataProjecao ? formatDate(dataProjecao) : '—'}
                            </span>
                        </div>
                    </div>

                    {/* ── Stats: Ganho + MOIC/Duração ── */}
                    <div className={cn('flex gap-2', !isMobile && 'flex-1')}>
                        <div
                            className={cn(
                                'flex flex-1 flex-col gap-0.5',
                                isMobile
                                    ? 'rounded-[10px] border border-stroke bg-[#f8fafb] px-3 py-2.5 dark:border-[#1a2228] dark:bg-[#0c1117]'
                                    : 'justify-center py-2',
                            )}
                        >
                            <span className="text-[9px] font-bold uppercase tracking-widest text-[#8a9097] dark:text-[#3d4850]">
                                Ganho Projetado
                            </span>
                            <span
                                className={cn(
                                    'font-semibold tabular-nums',
                                    isMobile ? 'text-[13px]' : 'mt-1 text-[20px]',
                                    ganho >= 0 ? 'text-[#0b1014] dark:text-white' : 'text-red-500',
                                )}
                            >
                                {ganho >= 0 ? '+' : ''}
                                {formatCurrency(ganho)}
                            </span>
                        </div>
                        <div
                            className={cn(
                                'flex flex-1 flex-col gap-0.5',
                                isMobile
                                    ? 'rounded-[10px] border border-stroke bg-[#f8fafb] px-3 py-2.5 dark:border-[#1a2228] dark:bg-[#0c1117]'
                                    : 'justify-center py-2',
                            )}
                        >
                            <span className="text-[9px] font-bold uppercase tracking-widest text-[#8a9097] dark:text-[#3d4850]">
                                MOIC · Duração
                            </span>
                            <div className={cn('flex items-baseline gap-1.5', !isMobile && 'mt-1')}>
                                <span
                                    className={cn(
                                        'font-semibold tabular-nums text-[#0b1014] dark:text-white',
                                        isMobile ? 'text-[13px]' : 'text-[20px]',
                                    )}
                                >
                                    {fmtMoic(moic)}
                                </span>
                                <span
                                    className={cn(
                                        'text-[#536471] dark:text-[#5d6770]',
                                        isMobile ? 'truncate text-[10px]' : 'text-[14px]',
                                    )}
                                >
                                    · {durationLabel || '—'}
                                </span>
                            </div>
                        </div>
                    </div>

                    {/* ── Botões de navegação secundária ── */}
                    <div className="flex gap-2">
                        <button
                            onClick={() => setIsProjectionOpen(true)}
                            className="rounded-lg border border-[#96FF00]/20 bg-[#96FF00]/6 px-3.5 py-1.5 text-[11px] font-semibold text-[#4d8f00] transition-all hover:bg-[#96FF00]/10 dark:border-[#96FF00]/15 dark:bg-[#96FF00]/4 dark:text-[#96FF00]/80 dark:hover:bg-[#96FF00]/[0.07]"
                        >
                            Projeção
                        </button>
                        <button
                            onClick={() => setIsDocsOpen(true)}
                            className="rounded-lg border border-stroke bg-[#f5f7fa] px-3.5 py-1.5 text-[11px] font-semibold text-[#8a9097] transition-all hover:text-[#536471] dark:border-[#1a2228] dark:bg-[#0c1117] dark:text-[#3d4850] dark:hover:text-[#6f7a83]"
                        >
                            Documentos
                        </button>
                    </div>

                    {/* ── Timeline de progresso ── */}
                    <div className="flex flex-col gap-1.5">
                        <div className="flex items-center justify-between text-[9px] font-medium text-[#8a9097] dark:text-[#3d4850]">
                            <span>Aquisição</span>
                            {dataProjecao && (
                                <span className="text-[#536471] dark:text-[#5d6770]">
                                    {remainingMonthsLabel}
                                </span>
                            )}
                            <span>Previsão</span>
                        </div>
                        <div className="relative h-[4px] overflow-hidden rounded-full bg-[#e8edf3] dark:bg-[#0c1117]">
                            {progressPct > 0 && (
                                <div
                                    className="absolute inset-y-0 left-0 rounded-full bg-[#96FF00] transition-all duration-700 dark:bg-[#96FF00]/70"
                                    style={{ width: `${progressPct}%` }}
                                />
                            )}
                        </div>
                        <div className="flex items-center justify-between text-[9px] tabular-nums text-[#8a9097] dark:text-[#3d4850]">
                            <span>{dataAquisicao ? dateFormater(dataAquisicao) : '—'}</span>
                            <span>{dataProjecao ? formatDate(dataProjecao) : '—'}</span>
                        </div>
                    </div>
                </div>

                {/*
                  Bolso do recorte (clip-path top-right): ícones centralizados no canto.
                  Ficam fora do overflow/clip do card para não serem cortados.
                */}
                {!isMobile && hasActions && (
                    <div
                        className="absolute -top-9 right-1.5 z-20 flex h-[clamp(2.75rem,9.5%,4rem)] w-[clamp(10rem,15%,14.5rem)] items-center justify-center sm:-top-11 sm:right-2 xl:top-[-3.25rem]"
                        role="toolbar"
                        aria-label="Ações do ativo"
                    >
                        <div className="flex items-center gap-1 sm:gap-1.5">
                            {onCreateCessionarioClick && (
                                <DesktopActionOrb
                                    icon={UserPlus}
                                    label="Cadastrar cessionário"
                                    onClick={onCreateCessionarioClick}
                                />
                            )}
                            {onListCessionariosClick && (
                                <DesktopActionOrb
                                    icon={Users}
                                    label="Cessionários cadastrados"
                                    onClick={onListCessionariosClick}
                                />
                            )}
                            {onArchivedClick && (
                                <DesktopActionOrb
                                    icon={FolderOpen}
                                    label="Ativos Arquivados"
                                    onClick={onArchivedClick}
                                />
                            )}

                            {isMaster && !isFromDasi && (
                                <CircularCommandMenu
                                    radius={110}
                                    startAngle={87}
                                    sweepAngle={95}
                                    triggerLabel="Ações gerais"
                                    triggerButtonClassName="h-9 w-9 xl:h-10 xl:w-10"
                                    items={[
                                        {
                                            id: 'archive',
                                            icon: <Archive className="h-4 w-4" />,
                                            label: 'Arquivar este ativo',
                                            tooltipSide: 'bottom',
                                            onClick: () => archiveTriggerRef.current?.click(),
                                        },
                                        {
                                            id: 'edit',
                                            icon: <Pencil className="h-4 w-4" />,
                                            label: 'Editar este Ativo',
                                            onClick: () => onEditItem?.(investment.id),
                                            tooltipSide: 'bottom',
                                        },
                                        {
                                            id: 'add',
                                            icon: <Plus className="h-4 w-4" />,
                                            label: 'Adicionar novo Ativo',
                                            onClick: onNewItem,
                                        },
                                        {
                                            id: 'export',
                                            icon: <FileSpreadsheet className="h-4 w-4" />,
                                            label: 'Exportar ativos para Excel',
                                            tooltipSide: 'left',
                                            onClick: onExportClick,
                                        },
                                        {
                                            id: 'import-history',
                                            icon: <FileClock className="h-4 w-4" />,
                                            label: 'Histórico de importações',
                                            tooltipSide: 'left',
                                            onClick: onImportHistoryClick,
                                        },
                                    ]}
                                />
                            )}
                        </div>
                    </div>
                )}
            </div>

            {/* Modais */}
            <ProjectionEvolutionModal
                isOpen={isProjectionOpen}
                onClose={() => setIsProjectionOpen(false)}
                posAquisicaoId={investment.id}
            />
            <PostPurchaseDocumentsModal
                isOpen={isDocsOpen}
                onClose={() => setIsDocsOpen(false)}
                posId={investment.id}
            />
            <ArchivePostPurchaseModal
                precatorioId={investment.id}
                triggerButton={
                    <button ref={archiveTriggerRef} className="sr-only" type="button" aria-hidden>
                        Arquivar
                    </button>
                }
            />
        </>
    );
}

