11	    TableRow,
12	} from '@/components/ui/table';
13	import { useComparativoCenarios } from '@/hooks/queries/useComparativoCenarios';
14	import { formatCompactNumber } from '@/functions/formaters/formatCompactNumber';
15	import {
16	    HoverCard,
17	    HoverCardContent,
18	    HoverCardPortal,
19	    HoverCardTrigger,
20	} from '@/components/ui/hover-card';
21	import {
22	    Area,
23	    AreaChart,
24	    CartesianGrid,
25	    ReferenceArea,
26	    ReferenceLine,
27	    ResponsiveContainer,
28	    Tooltip as RechartsTooltip,
29	    XAxis,
30	    YAxis,
31	} from 'recharts';
32	import { Loader2, X } from 'lucide-react';
33	import { formatDate } from '../../utils';
34	import type {
35	    ComparativoCenariosResponse,
36	    ComparativoScenarioKey,
37	    ComparativoTimelineEntry,
38	} from '@/types/comparativo-cenarios';
39	import { cn } from '@/lib/utils';
40	
41	interface ProjectionEvolutionModalProps {
42	    isOpen: boolean;
43	    onClose: () => void;
44	    posAquisicaoId: string | null;
45	}
46	
47	const SCENARIO_ORDER: ComparativoScenarioKey[] = ['optimistic', 'base', 'conservative'];
48	
49	const SCENARIO_LABELS: Record<ComparativoScenarioKey, string> = {
50	    optimistic: 'Otimista',
51	    base: 'Base',
52	    conservative: 'Conservador',
53	};
54	
55	const SCENARIO_CHART_COLORS: Record<ComparativoScenarioKey, string> = {
56	    optimistic: '#3b82f6',
57	    base: '#10b981',
58	    conservative: '#d97706',
59	};
60	
61	const SCENARIO_RING: Record<ComparativoScenarioKey, string> = {
62	    optimistic: 'ring-blue-500/45',
63	    base: 'ring-emerald-500/45',
64	    conservative: 'ring-amber-600/45',
65	};
66	
67	/** Traços distintos para as três séries terem o mesmo peso visual (sem área preenchida). */
68	const SCENARIO_LINE_DASH: Record<ComparativoScenarioKey, string | undefined> = {
69	    optimistic: undefined,
70	    base: '6 4',
71	    conservative: '2 4',
72	};
73	
74	interface ProjectionChartTooltipPayloadItem {
75	    name?: string;
76	    value?: number | string;
77	    dataKey?: string | number;
78	    color?: string;
79	}
80	
81	interface ProjectionChartTooltipProps {
82	    active?: boolean;
83	    payload?: ProjectionChartTooltipPayloadItem[];
84	    label?: string | number;
85	    formatCurrency: (value: number) => string;
86	    formatDateLabel: (value: string) => string;
87	}
88	
89	function ProjectionChartTooltip({
90	    active,
91	    payload,
92	    label,
93	    formatCurrency,
94	    formatDateLabel,
95	}: ProjectionChartTooltipProps) {
96	    if (!active || !payload?.length) return null;
97	    return (
98	        <div className="min-w-[220px] overflow-hidden rounded-3xl border border-border/40 bg-background/90 p-4 shadow-2xl backdrop-blur-2xl dark:border-white/5 dark:bg-black/85">
99	            <div className="mb-4 flex items-center gap-2 border-b border-border/40 pb-3">
100	                <span className="h-2.5 w-2.5 rounded-full bg-foreground/70" />
101	                <p className="font-mono text-[10px] font-bold uppercase tracking-[0.24em] text-muted-foreground/80">
102	                    {formatDateLabel(String(label))}
103	                </p>
104	            </div>
105	            <ul className="flex flex-col gap-3">
