156	function buildMergedChartData(data: ComparativoCenariosResponse) {
157	    const monthSet = new Set<string>();
158	    for (const k of SCENARIO_ORDER) {
159	        data.timelines[k]?.forEach((t) => monthSet.add(t.month));
160	    }
161	    return Array.from(monthSet)
162	        .sort()
163	        .map((month) => {
164	            const row: Record<string, string | number | null> = { month };
165	            for (const k of SCENARIO_ORDER) {
166	                row[k] = data.timelines[k]?.find((t) => t.month === month)?.projected_value ?? null;
167	            }
168	            return row;
169	        });
170	}
171	
172	interface UnifiedProjectionRow {
173	    month: string;
174	    entryByScenario: Partial<Record<ComparativoScenarioKey, ComparativoTimelineEntry>>;
175	}
176	
177	/** União dos cenários (fallback se não houver timeline conservadora). */
178	function buildUnifiedProjectionRows(data: ComparativoCenariosResponse): UnifiedProjectionRow[] {
179	    const monthSet = new Set<string>();
180	    for (const k of SCENARIO_ORDER) {
181	        data.timelines[k]?.forEach((t) => monthSet.add(t.month));
182	    }
183	    return Array.from(monthSet)
184	        .sort()
185	        .map((month) => {
186	            const entryByScenario: Partial<
187	                Record<ComparativoScenarioKey, ComparativoTimelineEntry>
188	            > = {};
189	            for (const k of SCENARIO_ORDER) {
190	                const e = data.timelines[k]?.find((t) => t.month === month);
191	                if (e) entryByScenario[k] = e;
192	            }
193	            return { month, entryByScenario };
194	        });
195	}
196	
197	function pickRepresentativeEntry(row: UnifiedProjectionRow): ComparativoTimelineEntry | undefined {
198	    return (
199	        row.entryByScenario.conservative ??
200	        row.entryByScenario.base ??
201	        row.entryByScenario.optimistic
202	    );
203	}
204	
205	/** Linhas da tabela: preferência pela timeline conservadora (contém base/otimista); fallback = união. */
206	function buildProjectionTableRows(
207	    data: ComparativoCenariosResponse,
208	): Array<{ month: string; entry: ComparativoTimelineEntry }> {
209	    const conservative = data.timelines.conservative;
210	    if (conservative?.length) {
211	        return conservative.map((entry) => ({ month: entry.month, entry }));
212	    }
213	    return buildUnifiedProjectionRows(data)
214	        .map((row) => {
215	            const entry = pickRepresentativeEntry(row);
216	            return entry ? { month: row.month, entry } : null;
217	        })
218	        .filter((x): x is { month: string; entry: ComparativoTimelineEntry } => x != null);
219	}
220	
221	function getFinalScenarioKeysForMonth(
222	    month: string,
223	    data: ComparativoCenariosResponse,
224	): ComparativoScenarioKey[] {
225	    if (!data?.scenario) return [];
226	    return SCENARIO_ORDER.filter(
227	        (k) => data.scenario?.[k]?.previsao_pagamento?.slice(0, 7) === month.slice(0, 7),
228	    );
229	}
230	
231	function buildGraceRanges(timeline: ComparativoTimelineEntry[] | undefined) {
232	    if (!timeline?.length) return [];
233	    return timeline.reduce<{ start: string; end?: string }[]>((acc, curr, idx) => {
234	        if (curr.in_grace_period) {
235	            if (acc.length === 0 || acc[acc.length - 1].end) {
236	                acc.push({ start: curr.month });
237	            }
238	        } else {
239	            if (acc.length > 0 && !acc[acc.length - 1].end) {
240	                acc[acc.length - 1].end = timeline[idx - 1]?.month ?? curr.month;
241	            }
242	        }
243	        if (idx === timeline.length - 1 && acc.length > 0 && !acc[acc.length - 1].end) {
244	            acc[acc.length - 1].end = curr.month;
245	        }
246	        return acc;
247	    }, []);
248	}
