'use client';

import { useMemo } from 'react';
import { Dialog, DialogContent, DialogTitle } from '@/components/ui/dialog';
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from '@/components/ui/table';
import { useComparativoCenarios } from '@/hooks/queries/useComparativoCenarios';
import { formatCompactNumber } from '@/functions/formaters/formatCompactNumber';
import {
    HoverCard,
    HoverCardContent,
    HoverCardPortal,
    HoverCardTrigger,
} from '@/components/ui/hover-card';
import {
    Area,
    AreaChart,
    CartesianGrid,
    ReferenceArea,
    ReferenceLine,
    ResponsiveContainer,
    Tooltip as RechartsTooltip,
    XAxis,
    YAxis,
} from 'recharts';
import { Loader2, X } from 'lucide-react';
import { formatDate } from '../../utils';
import type {
    ComparativoCenariosResponse,
    ComparativoScenarioKey,
    ComparativoTimelineEntry,
} from '@/types/comparativo-cenarios';
import { cn } from '@/lib/utils';

interface ProjectionEvolutionModalProps {
    isOpen: boolean;
    onClose: () => void;
    posAquisicaoId: string | null;
}

const SCENARIO_ORDER: ComparativoScenarioKey[] = ['optimistic', 'base', 'conservative'];

const SCENARIO_LABELS: Record<ComparativoScenarioKey, string> = {
    optimistic: 'Otimista',
    base: 'Base',
    conservative: 'Conservador',
};

const SCENARIO_CHART_COLORS: Record<ComparativoScenarioKey, string> = {
    optimistic: '#3b82f6',
    base: '#10b981',
    conservative: '#d97706',
};

const SCENARIO_RING: Record<ComparativoScenarioKey, string> = {
    optimistic: 'ring-blue-500/45',
    base: 'ring-emerald-500/45',
    conservative: 'ring-amber-600/45',
};

/** Traços distintos para as três séries terem o mesmo peso visual (sem área preenchida). */
const SCENARIO_LINE_DASH: Record<ComparativoScenarioKey, string | undefined> = {
    optimistic: undefined,
    base: '6 4',
    conservative: '2 4',
};

interface ProjectionChartTooltipPayloadItem {
    name?: string;
    value?: number | string;
    dataKey?: string | number;
    color?: string;
}

interface ProjectionChartTooltipProps {
    active?: boolean;
    payload?: ProjectionChartTooltipPayloadItem[];
    label?: string | number;
    formatCurrency: (value: number) => string;
    formatDateLabel: (value: string) => string;
}

function ProjectionChartTooltip({
    active,
    payload,
    label,
    formatCurrency,
    formatDateLabel,
}: ProjectionChartTooltipProps) {
    if (!active || !payload?.length) return null;
    return (
        <div className="min-w-[220px] overflow-hidden rounded-3xl border border-border/40 bg-background/90 p-4 shadow-2xl backdrop-blur-2xl dark:border-white/5 dark:bg-black/85">
            <div className="mb-4 flex items-center gap-2 border-b border-border/40 pb-3">
                <span className="h-2.5 w-2.5 rounded-full bg-foreground/70" />
                <p className="font-mono text-[10px] font-bold uppercase tracking-[0.24em] text-muted-foreground/80">
                    {formatDateLabel(String(label))}
                </p>
            </div>
            <ul className="flex flex-col gap-3">
                {payload.map((item, index) => {
                    const key = item.dataKey as ComparativoScenarioKey;
                    const raw = item.value;
                    if (raw == null || raw === '') return null;
                    const isConservative = key === 'conservative';
                    const title = isConservative
                        ? 'Conservador'
                        : (SCENARIO_LABELS[key] ?? String(item.name ?? key));
                    const isBase = key === 'base';

                    return (
                        <li
                            key={`${String(item.dataKey)}-${index}`}
                            className="flex flex-col gap-1 sm:flex-row sm:items-center sm:justify-between sm:gap-8"
                        >
                            <div className="flex items-center gap-2">
                                <span
                                    className="h-2.5 w-2.5 rounded-full ring-2 ring-offset-2 ring-offset-background"
                                    style={{
                                        backgroundColor: item.color ?? SCENARIO_CHART_COLORS[key],
                                        boxShadow: `0 0 0 1px ${item.color ?? SCENARIO_CHART_COLORS[key]}22`,
                                    }}
                                />
                                <span
                                    className={cn(
                                        'font-mono text-[11px] font-bold uppercase tracking-wider',
                                        isConservative
                                            ? 'text-amber-600 dark:text-amber-400'
                                            : isBase
                                              ? 'text-emerald-600 dark:text-emerald-400'
                                              : 'text-blue-600 dark:text-blue-400',
                                    )}
                                >
                                    {title}
                                </span>
                            </div>
                            <span
                                className="font-serif text-base tracking-tight text-foreground"
                                style={item.color ? { color: item.color } : undefined}
                            >
                                {formatCurrency(Number(raw))}
                            </span>
                        </li>
                    );
                })}
            </ul>
        </div>
    );
}

function buildMergedChartData(data: ComparativoCenariosResponse) {
    const monthSet = new Set<string>();
    for (const k of SCENARIO_ORDER) {
        data.timelines[k]?.forEach((t) => monthSet.add(t.month));
    }
    return Array.from(monthSet)
        .sort()
        .map((month) => {
            const row: Record<string, string | number | null> = { month };
            for (const k of SCENARIO_ORDER) {
                row[k] = data.timelines[k]?.find((t) => t.month === month)?.projected_value ?? null;
            }
            return row;
        });
}

interface UnifiedProjectionRow {
    month: string;
    entryByScenario: Partial<Record<ComparativoScenarioKey, ComparativoTimelineEntry>>;
}

/** União dos cenários (fallback se não houver timeline conservadora). */
function buildUnifiedProjectionRows(data: ComparativoCenariosResponse): UnifiedProjectionRow[] {
    const monthSet = new Set<string>();
    for (const k of SCENARIO_ORDER) {
        data.timelines[k]?.forEach((t) => monthSet.add(t.month));
    }
    return Array.from(monthSet)
        .sort()
        .map((month) => {
            const entryByScenario: Partial<
                Record<ComparativoScenarioKey, ComparativoTimelineEntry>
            > = {};
            for (const k of SCENARIO_ORDER) {
                const e = data.timelines[k]?.find((t) => t.month === month);
                if (e) entryByScenario[k] = e;
            }
            return { month, entryByScenario };
        });
}

function pickRepresentativeEntry(row: UnifiedProjectionRow): ComparativoTimelineEntry | undefined {
    return (
        row.entryByScenario.conservative ??
        row.entryByScenario.base ??
        row.entryByScenario.optimistic
    );
}

/** Linhas da tabela: preferência pela timeline conservadora (contém base/otimista); fallback = união. */
function buildProjectionTableRows(
    data: ComparativoCenariosResponse,
): Array<{ month: string; entry: ComparativoTimelineEntry }> {
    const conservative = data.timelines.conservative;
    if (conservative?.length) {
        return conservative.map((entry) => ({ month: entry.month, entry }));
    }
    return buildUnifiedProjectionRows(data)
        .map((row) => {
            const entry = pickRepresentativeEntry(row);
            return entry ? { month: row.month, entry } : null;
        })
        .filter((x): x is { month: string; entry: ComparativoTimelineEntry } => x != null);
}

function getFinalScenarioKeysForMonth(
    month: string,
    data: ComparativoCenariosResponse,
): ComparativoScenarioKey[] {
    if (!data?.scenario) return [];
    return SCENARIO_ORDER.filter(
        (k) => data.scenario?.[k]?.previsao_pagamento?.slice(0, 7) === month.slice(0, 7),
    );
}

function buildGraceRanges(timeline: ComparativoTimelineEntry[] | undefined) {
    if (!timeline?.length) return [];
    return timeline.reduce<{ start: string; end?: string }[]>((acc, curr, idx) => {
        if (curr.in_grace_period) {
            if (acc.length === 0 || acc[acc.length - 1].end) {
                acc.push({ start: curr.month });
            }
        } else {
            if (acc.length > 0 && !acc[acc.length - 1].end) {
                acc[acc.length - 1].end = timeline[idx - 1]?.month ?? curr.month;
            }
        }
        if (idx === timeline.length - 1 && acc.length > 0 && !acc[acc.length - 1].end) {
            acc[acc.length - 1].end = curr.month;
        }
        return acc;
    }, []);
}

export function ProjectionEvolutionModal({
    isOpen,
    onClose,
    posAquisicaoId,
}: ProjectionEvolutionModalProps) {
    const { data, isLoading, isFetching } = useComparativoCenarios(isOpen ? posAquisicaoId : null);
    const isRefetching = isFetching && !isLoading;

    const chartData = useMemo(() => (data ? buildMergedChartData(data) : []), [data]);

    const projectionTableRows = useMemo(() => (data ? buildProjectionTableRows(data) : []), [data]);

    const graceTimeline = useMemo(() => {
        if (!data) return undefined;
        return (
            data.timelines.conservative ?? data.timelines.base ?? data.timelines.optimistic ?? []
        );
    }, [data]);

    const graceRanges = useMemo(() => buildGraceRanges(graceTimeline), [graceTimeline]);

    const formatCurrency = (value: number) => {
        return new Intl.NumberFormat('pt-BR', {
            style: 'currency',
            currency: 'BRL',
        }).format(value);
    };

    const formatFactor = (value: number) => {
        return new Intl.NumberFormat('pt-BR', {
            minimumFractionDigits: 8,
            maximumFractionDigits: 8,
        }).format(value);
    };

    const formatPct = (value: number) => `${(value * 100).toFixed(2)}%`;

    return (
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent className="max-h-[95vh] w-full max-w-6xl overflow-y-auto border-border/40 bg-background/95 p-0 shadow-2xl backdrop-blur-3xl dark:bg-black/95 sm:max-h-[90vh]">
                <div className="sticky top-0 z-30 flex flex-col gap-2 border-b border-border/40 bg-background/80 px-4 py-4 backdrop-blur-xl dark:bg-black/80 sm:px-6 sm:py-6 lg:px-10">
                    <div className="flex items-center justify-between">
                        <DialogTitle className="font-serif text-2xl tracking-tight sm:text-3xl md:text-4xl lg:text-5xl">
                            Evolução do Ativo
                        </DialogTitle>
                        <button
                            onClick={onClose}
                            className="rounded-full p-2 text-muted-foreground/50 transition-colors hover:bg-foreground/5 hover:text-foreground"
                        >
                            <X size={18} />
                        </button>
                    </div>
                    <p className="font-mono line-clamp-1 text-[10px] font-semibold uppercase tracking-[0.2em] text-muted-foreground/70">
                        Projeções & Cenários Comparativos · Recálculo dinâmico indexado
                    </p>
                </div>

                <div className="w-full min-w-0 px-4 pb-8 pt-5 sm:px-6 sm:pb-10 sm:pt-8 lg:px-10">
                    {isLoading ? (
