                                        </TableBody>
                                    </Table>
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="flex h-64 flex-col items-center justify-center">
                            <p className="font-mono text-xs uppercase tracking-[0.2em] text-muted-foreground/60">
                                Não foi possível carregar as projeções.
                            </p>
                        </div>
                    )}
                </div>
            </DialogContent>
        </Dialog>
    );
}

