import { resolveDueResponsavel } from '@/functions/due-diligence/resolve-due-responsavel';
import { formatCurrency } from '@/functions/formaters/formatCurrency';
import { GetDueDiligenceByIdResponse } from '@/interfaces/IDueDiligence';
import { formatDate } from 'date-fns';
import {
    CalendarIcon,
    CheckCircleIcon,
    ClockIcon,
    FileTextIcon,
    UserIcon,
    XCircleIcon
} from 'lucide-react';
import { Avatar, AvatarFallback, AvatarImage } from '../ui/avatar';
import { Badge } from '../ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '../ui/dialog';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../ui/tabs';

interface DueDiligenceModalProps {
    isOpen: boolean;
    onClose: () => void;
    dueDiligence: GetDueDiligenceByIdResponse;
}

export function DueDiligenceModal({ isOpen, onClose, dueDiligence }: DueDiligenceModalProps) {
    const responsavelEffective = resolveDueResponsavel(dueDiligence);

    const resolveDueStatus = (status: string) => {
        const formated = status.replace('_', ' ').toLowerCase();
        return formated;
    };

    const resolvedDueStatus = resolveDueStatus(dueDiligence.status);

    const getStatusColor = (status: string) => {
        switch (status.toLowerCase()) {
            case 'pendente':
                return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-300';
            case 'concluido':
                return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300';
            case 'rejeitado':
                return 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300';
            default:
                return 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-300';
        }
    };

    const getStatusIcon = (status: string) => {
        switch (status.toLowerCase()) {
            case 'pendente':
                return <ClockIcon className="h-4 w-4" />;
            case 'concluido':
                return <CheckCircleIcon className="h-4 w-4" />;
            case 'rejeitado':
                return <XCircleIcon className="h-4 w-4" />;
            default:
                return <FileTextIcon className="h-4 w-4" />;
        }
    };
    return (
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent className="max-h-[90vh] max-w-4xl overflow-y-auto">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2">
                        <FileTextIcon className="h-5 w-5" />
                        Due Diligence #{dueDiligence.proposta_origem}
                    </DialogTitle>
                </DialogHeader>

                <div className="space-y-6">
                    <Card>
                        <CardHeader>
                            <CardTitle className="flex items-center justify-between">
                                <span>Informações Gerais</span>
                                <Badge className={getStatusColor(dueDiligence.status_display ?? resolvedDueStatus)}>
                                    {getStatusIcon(dueDiligence.status_display ?? resolvedDueStatus)}
                                    <span className="ml-1">{dueDiligence.status_display ?? resolvedDueStatus}</span>
                                </Badge>
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="grid grid-cols-1 gap-4 md:grid-cols-2">
                            <div className="space-y-2">
                                <p>
                                    <span className="font-semibold">Broker:</span>{' '}
                                    {dueDiligence.broker.nome || dueDiligence.broker.username}
                                </p>
                                <p>
                                    <span className="font-semibold">Coordenador:</span>{' '}
                                    {dueDiligence.coordenador ?? 'Não informado'}
                                </p>
                                <p>
                                    <span className="font-semibold">Regime:</span>{' '}
                                    {dueDiligence.regime}
                                </p>
                                <p>
                                    <span className="font-semibold">Valor Líquido:</span>{' '}
                                    {formatCurrency(dueDiligence.valor_liquido_disponivel)}
                                </p>
                            </div>
                            <div className="space-y-2">
                                <p>
                                    <span className="font-semibold">LOA:</span> {dueDiligence.loa}
                                </p>
                                <p>
                                    <span className="font-semibold">Esfera:</span>{' '}
                                    {dueDiligence.esfera}
                                </p>
                                <p>
                                    <span className="font-semibold">Tribunal:</span>{' '}
                                    {dueDiligence.tribunal}
                                </p>
                            </div>
                        </CardContent>
                    </Card>

                    <Card>
                        <CardHeader>
                            <CardTitle className="flex items-center gap-2">
                                <UserIcon className="h-5 w-5 shrink-0" />
                                Responsável
                            </CardTitle>
                        </CardHeader>
                        <CardContent>
                            {responsavelEffective ? (
                                <div className="flex items-center gap-4">
                                    <Avatar>
                                        <AvatarImage
                                            src={
                                                responsavelEffective.profile_picture ||
                                                '/placeholder.svg'
                                            }
                                            className="object-cover"
                                        />
                                        <AvatarFallback>
                                            {responsavelEffective.first_name[0]}
                                            {responsavelEffective.last_name[0]}
                                        </AvatarFallback>
                                    </Avatar>
                                    <div>
                                        <p className="font-medium">
                                            {responsavelEffective.first_name}{' '}
                                            {responsavelEffective.last_name}
                                        </p>
                                        <p className="text-sm text-muted-foreground">
                                            {responsavelEffective.role_display}
                                        </p>
                                        <p className="text-sm text-muted-foreground">
                                            {responsavelEffective.email}
                                        </p>
                                        <p className="text-sm text-muted-foreground">
                                            {responsavelEffective.phone}
                                        </p>
                                    </div>
                                </div>
                            ) : (
                                <p className="text-sm text-muted-foreground">
                                    Nenhum responsável designado nesta diligência.
                                </p>
                            )}
                        </CardContent>
                    </Card>

                    <Tabs defaultValue="checklist" className="w-full">
                        <TabsList className="grid w-full grid-cols-3">
                            <TabsTrigger value="checklist">Checklist</TabsTrigger>
                            <TabsTrigger value="repactuacoes">Repactuações</TabsTrigger>
                            <TabsTrigger value="esteira">Esteira</TabsTrigger>
                        </TabsList>

                        <TabsContent value="checklist" className="space-y-4">
                            <Card>
                                <CardHeader>
                                    <CardTitle>Itens do Checklist</CardTitle>
                                </CardHeader>
                                <CardContent className="space-y-4">
                                    {dueDiligence.itens_checklist?.length > 0 ?
                                        dueDiligence.itens_checklist.map((item) => (
                                            <div key={item.id} className="rounded-lg border p-4">
                                                <div className="mb-2 flex items-center justify-between">
                                                    <h4 className="font-medium">
                                                        {item.requisito.nome}
                                                    </h4>
                                                    <Badge
                                                        className={getStatusColor(
                                                            item.status_display ?? resolvedDueStatus
                                                        )}
                                                    >
                                                        {getStatusIcon(item.status_display ?? resolvedDueStatus)}
                                                        <span className="ml-1">
                                                            {item.status_display ?? resolvedDueStatus}
                                                        </span>
                                                    </Badge>
                                                </div>
                                                <p className="mb-2 text-sm text-muted-foreground">
                                                    {item.requisito.descricao}
                                                </p>
                                                {item.observacao && (
                                                    <p className="text-sm">
                                                        <strong>Observação:</strong>{' '}
                                                        {item.observacao}
                                                    </p>
                                                )}
                                                {item.verificado_por && (
                                                    <div className="mt-2 flex items-center gap-2">
                                                        <Avatar className="h-6 w-6">
                                                            <AvatarImage
                                                                src={
                                                                    item.verificado_por
                                                                        .profile_picture ||
                                                                    '/placeholder.svg'
                                                                }
                                                                className="object-cover"
                                                            />
                                                            <AvatarFallback className="text-xs">
                                                                {item.verificado_por.first_name[0]}
                                                                {item.verificado_por.last_name[0]}
                                                            </AvatarFallback>
                                                        </Avatar>
                                                        <span className="text-xs text-muted-foreground">
                                                            Verificado por{' '}
                                                            {item.verificado_por.first_name}{' '}
                                                            {item.verificado_por.last_name}
                                                        </span>
                                                    </div>
                                                )}
                                            </div>
                                        )) : <p className="text-sm text-muted-foreground">Nenhum item de checklist encontrado.</p>}
                                </CardContent>
                            </Card>
                        </TabsContent>

                        <TabsContent value="repactuacoes" className="space-y-4">
                            <Card>
                                <CardHeader>
                                    <CardTitle>Histórico de Repactuações</CardTitle>
                                </CardHeader>
                                <CardContent className="space-y-4">
                                    {dueDiligence.repactuacoes &&
                                        dueDiligence.repactuacoes.map((repactuacao) => (
                                            <div
                                                key={repactuacao.id}
                                                className="rounded-lg border p-4"
                                            >
                                                <div className="mb-2 flex items-center justify-between">
                                                    <h4 className="font-medium">
                                                        Repactuação #{repactuacao.id}
                                                    </h4>
                                                    <Badge>{repactuacao.status}</Badge>
                                                </div>
                                                <div className="grid grid-cols-1 gap-4 text-sm md:grid-cols-2">
                                                    <div>
                                                        <p>
                                                            <span className="font-semibold">
                                                                Motivo:
                                                            </span>{' '}
                                                            {repactuacao.motivo || 'Não informado'}
                                                        </p>
                                                        <p>
                                                            <span className="font-semibold">
                                                                Due Diligence Origem:
                                                            </span>{' '}
                                                            {repactuacao.proposta_origem}
                                                        </p>
                                                        <p>
                                                            <span className="font-semibold">
                                                                Due Diligence Substituta:
                                                            </span>{' '}
                                                            {repactuacao.proposta_substituta ||
                                                                'Não informado'}
                                                        </p>
                                                    </div>
                                                    <div>
                                                        <p className="flex items-center gap-1">
                                                            <CalendarIcon className="h-4 w-4" />
                                                            <span className="font-semibold">
                                                                Início:
                                                            </span>{' '}
                                                            {formatDate(
                                                                repactuacao.data_inicio,
                                                                'dd/MM/yyyy',
                                                            )}
                                                        </p>
                                                        <p className="flex items-center gap-1">
                                                            <CalendarIcon className="h-4 w-4" />
                                                            <span className="font-semibold">
                                                                Fim:
                                                            </span>{' '}
                                                            {repactuacao.data_fim
                                                                ? formatDate(
                                                                    repactuacao.data_fim,
                                                                    'dd/MM/yyyy',
                                                                )
                                                                : 'Não informado'}
                                                        </p>
                                                    </div>
                                                </div>
                                                {repactuacao.observacoes && (
                                                    <p className="mt-2 text-sm">
                                                        <span className="font-semibold">
                                                            Observações:
                                                        </span>{' '}
                                                        {repactuacao.observacoes}
                                                    </p>
                                                )}
                                                <div className="mt-2 flex items-center gap-2">
                                                    <Avatar className="h-6 w-6">
                                                        <AvatarImage
                                                            src={
                                                                repactuacao.criado_por
                                                                    .profile_picture ||
                                                                '/placeholder.svg'
                                                            }
                                                            className="object-cover"
                                                        />
                                                        <AvatarFallback className="text-xs">
                                                            {repactuacao.criado_por.first_name[0]}
                                                            {repactuacao.criado_por.last_name[0]}
                                                        </AvatarFallback>
                                                    </Avatar>
                                                    <span className="text-xs text-muted-foreground">
                                                        Criado por{' '}
                                                        {repactuacao.criado_por.first_name}{' '}
                                                        {repactuacao.criado_por.last_name}
                                                    </span>
                                                </div>
                                            </div>
                                        ))}
                                </CardContent>
                            </Card>
                        </TabsContent>

                        <TabsContent value="esteira" className="space-y-4">
                            <Card>
                                <CardHeader>
                                    <CardTitle>Detalhes da Esteira</CardTitle>
                                </CardHeader>
                                <CardContent className="space-y-4">
                                    {dueDiligence.esteira_detail ? (
                                        <>
                                            <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                                                <div className="space-y-2">
                                                    <p>
                                                        <strong>Nome:</strong>{' '}
                                                        {dueDiligence.esteira_detail.nome}
                                                    </p>
                                                    <p>
                                                        <strong>Tipo:</strong>{' '}
                                                        {dueDiligence.esteira_detail.tipo_display}
                                                    </p>
                                                    <p>
                                                        <strong>Compensação:</strong>{' '}
                                                        {dueDiligence.esteira_detail.compensacao
                                                            ? 'Sim'
                                                            : 'Não'}
                                                    </p>
                                                </div>
                                                <div className="space-y-2">
                                                    <p>
                                                        <strong>Documentos:</strong>{' '}
                                                        {
                                                            dueDiligence.esteira_detail
                                                                .documentos_count
                                                        }
                                                    </p>
                                                    <p>
                                                        <strong>Customizada:</strong>{' '}
                                                        {dueDiligence.esteira_detail.customizada
                                                            ? 'Sim'
                                                            : 'Não'}
                                                    </p>
                                                </div>
                                            </div>
                                            <div>
                                                <p>
                                                    <strong>Descrição:</strong>
                                                </p>
                                                <p className="mt-1 text-sm text-muted-foreground">
                                                    {dueDiligence.esteira_detail.descricao}
                                                </p>
                                            </div>
                                        </>
                                    ) : (
                                        <p>Nenhum detalhe disponível.</p>
                                    )}
                                </CardContent>
                            </Card>
                        </TabsContent>
                    </Tabs>

                    {dueDiligence.observacoes && (
                        <Card>
                            <CardHeader>
                                <CardTitle>Observações</CardTitle>
                            </CardHeader>
                            <CardContent>
                                <p className="text-sm">{dueDiligence.observacoes}</p>
                            </CardContent>
                        </Card>
                    )}

                    <Card>
                        <CardHeader>
                            <CardTitle className="flex items-center gap-2">
                                <CalendarIcon className="h-5 w-5" />
                                Cronologia
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="grid grid-cols-1 gap-4 md:grid-cols-2">
                            <div>
                                <p>
                                    <span className="font-semibold">Data de Início:</span>{' '}
                                    {formatDate(dueDiligence.data_inicio, 'dd/MM/yyyy')}
                                </p>
                                <p>
                                    <span className="font-semibold">Data de Fim:</span>{' '}
                                    {formatDate(dueDiligence.data_fim, 'dd/MM/yyyy')}
                                </p>
                                {dueDiligence.data_finalizacao && (
                                    <p>
                                        <span className="font-semibold">Finalizada em:</span>{' '}
                                        {formatDate(dueDiligence.data_finalizacao, 'dd/MM/yyyy HH:mm')}
                                    </p>
                                )}
                            </div>
                            {/* <div>
                                <p>
                                    <span className="font-semibold">Criado em:</span>{' '}
                                    {formatDate(dueDiligence.created_at, 'dd/MM/yyyy')}
                                </p>
                                <p>
                                    <span className="font-semibold">Atualizado em:</span>{' '}
                                    {formatDate(dueDiligence.updated_at, 'dd/MM/yyyy')}
                                </p>
                            </div> */}
                        </CardContent>
                    </Card>
                </div>
            </DialogContent>
        </Dialog>
    );
}

