import { ColumnDef } from '@tanstack/react-table';
import { Button } from '@/components/ui/button';
import { ArrowUpDown } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import React from 'react';
import { formatDate } from 'date-fns';
import { ProcessualMove } from '@/interfaces/IProcessualMoves';
import ProcessualMoveTableDropdown from '@/components/Dropdowns/Broker/BrokerEventTableDropdown';

export const columns: ColumnDef<ProcessualMove>[] = [
    {
        id: 'createdAt',
        accessorKey: 'created_at',
        header: ({ column }) => {
            return (
                <Button
                    variant="ghost"
                    onClick={() => column.toggleSorting(column.getIsSorted() === 'asc')}
                    className="mx-auto flex items-center gap-2 text-center"
                >
                    Data
                    <ArrowUpDown size={14} />
                </Button>
            );
        },
        cell: ({ row }) => (
            <div className="text-center font-semibold">
                {formatDate(row.original.created_at, 'dd/MM/yyyy')}
            </div>
        ),
    },
    {
        id: 'description',
        accessorKey: 'descricao',
        header: () => 'Descrição',
        cell: ({ row }) => {
            const maxWidth = window.location.pathname.includes('dashboard/broker') ? 'max-w-80' : 'max-w-[790px]';

            return (
                <ProcessualMoveTableDropdown message={row.getValue('description')}>
                    <p className={`${maxWidth} truncate`}>
                        {row.getValue('description')}
                    </p>
                </ProcessualMoveTableDropdown>
            );
        },
    },
    {
        id: 'origem',
        accessorKey: 'properties.Origem.select.name',
        header: ({ column }) => {
            return (
                <Button
                    variant="ghost"
                    onClick={() => column.toggleSorting(column.getIsSorted() === 'asc')}
                    className="mx-auto flex items-center gap-2 text-center"
                >
                    Origem
                    <ArrowUpDown size={14} />
                </Button>
            );
        },
        cell: ({ row }) => {
            const origem = row.original.origem;
            switch (origem) {
                case 'Extração direta':
                    return (
                        <div className="flex w-full justify-center">
                            <Badge
                                variant={'default'}
                                className="mx-auto bg-green-100 text-green-800 hover:bg-current hover:bg-green-200 dark:bg-green-800 dark:text-green-100 dark:hover:bg-green-700"
                            >
                                {origem}
                            </Badge>
                        </div>
                    );
                case 'Inserção manual':
                    return (
                        <div className="flex w-full justify-center">
                            <Badge
                                variant={'default'}
                                className="bg-orange-100 text-orange-800 hover:bg-orange-200 dark:bg-orange-800 dark:text-orange-100 dark:hover:bg-orange-700"
                            >
                                {origem}
                            </Badge>
                        </div>
                    );
                default:
                    return (
                        <div className="flex w-full justify-center">
                            <Badge
                                variant={'default'}
                                className="text-gray-800 bg-gray-100 hover:bg-gray-200 dark:hover:bg-gray-700"
                            >
                                {origem as React.ReactNode}
                            </Badge>
                        </div>
                    );
            }
        },
    },
];

